inline double clamp50(double v) { return fabs(v) > 50.0 ? (v > 0.0 ? 50.0 : -50.0) : v; }
// The DLL clamps Im(z) to +-50 before sinh/cosh. In float32 sinh(50)^3 overflows (max ~3e38), which turns the
// quotients in formulas such as 7 and 9 into NaN and ends the loop early; +-30 keeps cubes finite and still
// leaves the quotient negligible, so the orbit behaves as it does in double precision.
inline double clampIm(double v) { return fabs(v) > 50.0 ? (v > 0.0 ? 50.0 : -50.0) : v; }
inline double guardTiny(double v) { return fabs(v) < 1e-25 ? (v > 0.0 ? 1e-25 : -1e-25) : v; }

inline void sine_cosine(cplx z,  cplx &zsin,  cplx &zcos) {
    double y = guardTiny(clampIm(z.y));
    double ey = std::exp(y);
    double ch = (1.0 / ey + ey) * 0.5;
    double sh = (ey - 1.0 / ey) * 0.5;
    double sx = sn(z.x);
    double cx = cs(z.x);
    zsin = cplx(ch * sx, cx * sh);
    zcos = cplx(ch * cx, -sx * sh);
}

inline cplx csin_z(cplx &z) { z.x = guardTiny(clamp50(z.x)); z.y = guardTiny(clamp50(z.y));
    double x = guardTiny(clamp50(z.x));
    double y = guardTiny(clampIm(z.y));
    double ey = std::exp(y);
    return cplx((1.0 / ey + ey) * 0.5 * sn(x), (ey - 1.0 / ey) * 0.5 * cs(x));
}

inline cplx cexp_z(cplx &z) { z.x = clamp50(z.x); z.y = clamp50(z.y);
    double ex = std::exp(clamp50(z.x)); // 30, not 50: e^50 times z^4 times a second factor overflows float32
    double y = clamp50(z.y);
    return cplx(ex * cs(y), ex * sn(y));
}

// C99 atan2 for a zero y: +-0 for x >= +0, +-pi for x <= -0 (the sign of y is kept).
inline double atan2c(double y, double x) {
    if (y == 0.0) return (x < 0.0 || signbit(x)) ? copysign(kPi, y) : copysign(0.0, y);
    return std::atan2(y, x);
}

inline cplx clog_z(cplx &z) { z.x = clamp50(z.x); z.y = clamp50(z.y);
    double x = clamp50(z.x);
    double y = clamp50(z.y);
    return cplx(std::log(sqrt(y * y + x * x)), atan2c(y, x));
}

inline cplx ctan_z(cplx z) {
    double x = guardTiny(clamp50(z.x));
    double y = guardTiny(clampIm(z.y));
    double ey = std::exp(y);
    double ch = (1.0 / ey + ey) * 0.5;
    double sh = (ey - 1.0 / ey) * 0.5;
    cplx s(ch * sn(x), sh * cs(x));
    cplx c(ch * cs(x), sh * -sn(x));
    return s / c;
}

