// The "Transform" menu, applied to each orbit point.
inline float2 applyTransform(int t, float2 p) {
    const double e = 1e-15;
    double x = p.x;
    double y = p.y;
    double nx;
    double ny;
    switch (t) {
    case 1:
        nx = e + sn(x - (e + sn(y)));
        ny = e + cs(y - (e + sn(nx)));
        break;
    case 2:
        nx = e + sn(e + sn(y) + x);
        ny = e + cs(e + sn(nx) + y);
        break;
    case 3:
        nx = e + atan(y / (e + x));
        ny = e + atan(nx / (e + y));
        break;
    case 4:
        nx = e + sn((e + sn(y)) * x);
        ny = e + cs((e + sn(nx)) * y);
        break;
    default:
        return p;
    }
    return float2(nx, ny);
}

