// ---------------------------------------------------------------------------------------------------------
// Orbit-trap renders 2...5 (FUN_0049d158 cases 2-5). `trapPoint` is also what the streaming  path uses.
// ---------------------------------------------------------------------------------------------------------

inline void trapPoint(int render, real radius, real px, real py,  real &sumA,  real &sumB) {
    real sx;
    real sy;
    if (render == 3) {
        real x = rAbs(px);
        real y = rAbs(py);
        if (x < TINY) x = TINY;
        if (y < TINY) y = TINY;
        real x2 = x * x;
        real y2 = y * y;
        sx = rAbs((rAbs(2.0 * x2) - rAbs(y2)) - rSin(y2 * y2));
        sy = rAbs((rAbs(2.0 * y2) - rAbs(x2)) - rSin(x2 * x2));
    } else if (render == 5) {
        real x = rAbs(px);
        real y = rAbs(py);
        sx = rLog(rAbs(rSin(6.28318530718 * x) + x) + 1.0);
        sy = rLog(rAbs(rSin(6.28318530718 * y) + y) + 1.0);
    } else {
        real x2 = px * px;
        real y2 = py * py;
        if (x2 < TINY) x2 = TINY;
        if (y2 < TINY) y2 = TINY;
        if (render == 2) {
            sx = rAbs(x2 * x2 - rAbs(y2 - rSin(x2)));
            sy = rAbs(y2 * y2 - rAbs(x2 - rSin(y2)));
        } else {
            sx = rAbs(rSin(y2) - rSin(x2));
            sy = rAbs(rSin(x2) - rSin(y2));
        }
    }
    if (sx < radius) sumA += 1.0 - sx / radius;
    if (sy < radius) sumB += 1.0 - sy / radius;
}

