            if (s.g7884 < minY && TINY < rAbs(s.g7884)) minY = s.g7884;
            s.g788c = rAbs(s.g7908) / (EPS15 + i);
            s.g7894 = rAbs(s.g7910) / (EPS15 + i);
            s.g7960 = s.g787c + s.g788c;
            s.g7970 = s.g7884 + s.g7894;
            s.g789c = s.g7960 * s.g7960 + s.g789c;
