        case 117: P = rSin(P - K) * B * rCos(P - K); break;
        case 118: P = rCos(P * K) * B * rSin(P * K); break;
        case 119: P = rSin(1.0 - K) * B * rCos(P * K) * rCos(P + K); break;
        case 120: P = B * K * rSin(P + K) * rCos(P + K); break;
