            L = (K - K * 2.0 * P) * L;
            d0 = ((y * y + x * x) - rAbs(x)) * d0;
            d8 = ((y * y + x * x) - rAbs(y)) * d8;
            same = false;
            break;
        case 2:
            L = 2.0 * B * rSin(P + K) * rCos(P + K) * L;
            d0 = ((rAbs(x * y) - rAbs(y)) + rSin(rAbs(y * y))) * d0;
            d8 = ((rAbs(x * y) - rAbs(x)) + rSin(rAbs(x * x))) * d8;
            same = false;
            break;
