// Argentic's formula 56: the classic quadratic escape-time map, separate from legacy Formula_00.
// Orbit 0 is initialized by the caller. Return stored orbit count (iterations + 1), except that
// render 1 uses count 0 for non-escaping points so every colour blend produces a black interior.
inline int classicMandelbrot( OrbitAcc &S, cplx initial, cplx parameter, int maxit, int jul) {
    cplx z = jul != 0 ? initial : cplx(0.0, 0.0);
    double escapeSquared = jul != 0 ? max(4.0, sum_sqrs(parameter)) : 4.0;
    if (jul == 0 && kRender == 1 && fabs(parameter.x) <= 2.0 && fabs(parameter.y) <= 2.0) {
        // Analytic interior tests for the main cardioid and period-2 bulb avoid long bounded loops.
        double x = parameter.x - 0.25;
        double y2 = parameter.y * parameter.y;
        double q = x * x + y2;
        double bulbX = parameter.x + 1.0;
        if (q * (q + x) <= 0.25 * y2 || bulbX * bulbX + y2 <= 0.0625) return 0;
    }
    for (int it = 1; it <= maxit; ++it) {
        z = z * z + parameter;
        S.add(z, it);
        if (!isfinite(z.x) || !isfinite(z.y) || sum_sqrs(z) > escapeSquared) return it + 1;
    }
    return kRender == 1 ? 0 : maxit + 1;
}

inline int evaluateFormula(int formula,  OrbitAcc &S, cplx vz, cplx vc, int maxit, int jul, double radius) {
    if (formula == kClassicMandelbrotFormulaID) return classicMandelbrot(S, vz, vc, maxit, jul);
    return runFormula(formula, S, vz, vc, maxit, jul, radius);
}

 void fieldKernel(const FieldParams &p ,
                         float2 *field ,
                         float2 *orbitBase ,
                        uint2 gid ) {
    if (int(gid.x) >= p.fieldWidth || int(gid.y) >= p.rowCount) return;
    int col = int(gid.x);
    int row = p.rowStart + int(gid.y);

    cplx z0(p.xMin + double(col) * p.dx, p.yMin + double(row) * p.dy);
    cplx c0 = p.juliaMode != 0 ? cplx(p.juliaX, p.juliaY) : z0;
    // FUN_0049b4d0 transforms the starting z and c of every pixel before running the formula.
    if (p.coordFlag == 1) {
        z0 = cplx(z0.y, z0.x);
        c0 = cplx(c0.y, c0.x);
    } else if (p.coordFlag == 2) {
        z0 = cplx(-z0.y, -z0.x);
        c0 = cplx(-c0.y, -c0.x);
    } else if (p.coordFlag == 3) {
        z0 = cplx(-z0.x, -z0.y);
        c0 = cplx(-c0.x, -c0.y);
    }
    if (p.insideOut != 0 && kFormula < 100) {
        // formula() in the DLL inverts both z and c, with exactly this expression order: it matters
        // for the sign of a zero imaginary part, which clog_z's atan2 then sees.
        double zd = z0.y * z0.y + z0.x * z0.x;
        z0 = cplx((z0.y * 0.0 + z0.x * 1.0) / zd, (z0.x * 0.0 - z0.y * 1.0) / zd);
        double cd = c0.y * c0.y + c0.x * c0.x;
        c0 = cplx((c0.y * 0.0 + c0.x * 1.0) / cd, (c0.x * 0.0 - c0.y * 1.0) / cd);
    }

    float2 result;
    if (kUseOrbit) {
        Orbit orb;
        orb.base = orbitBase;
        orb.stride = 1;
        orb.tid = 0;
        RS rs = rsInit(p.trapRadius, p.scale, p.maxIterations);
        int count;
        if (kFormula >= 100) {
            count = lyapunovRun(rs, orb, kFormula, p.lyMapping, p.lyDerivative, kRender,
                                c0.x, c0.y, p.insideOut != 0, p.maxIterations);
        } else {
            OrbitAcc S;
            S.radius = p.trapRadius;
            S.sumA = 0.0;
            S.sumB = 0.0;
            S.orb = orb;
            cplx start = kFormula == kClassicMandelbrotFormulaID && p.juliaMode != 0 ? z0 : cplx(0.0, 0.0);
            orb.set(0, start.x, start.y);
            count = evaluateFormula(kFormula, S, z0, c0, p.maxIterations, p.juliaMode, p.trapRadius);
        }
        rs.count = count;
        if (kTransform != 0) {
            for (int i = 0; i < count; i++) {
                float2 q = applyTransform(kTransform, float2(orb.X(i), orb.Y(i)));
                orb.set(i, q.x, q.y);
            }
        }
        renderArrays(kRender, rs, orb, c0.x, c0.y, p.lyDerivative);
        result = float2(rs.outA, rs.outB);
    } else {
        OrbitAcc S;
        S.radius = p.trapRadius;
        S.sumA = 0.0;
        S.sumB = 0.0;
        // pXTemp[0] / pYTemp[0] are always (0, 0) and the render stage reads them.
        S.add(kFormula == kClassicMandelbrotFormulaID && p.juliaMode != 0 ? z0 : cplx(0.0, 0.0), 0);

        int it = evaluateFormula(kFormula, S, z0, c0, p.maxIterations, p.juliaMode, p.trapRadius);

        if (kRender == 0) {
            result = float2(S.last.x, S.last.y);
        } else if (kRender == 1) {
            double v = fabs(log(1.0 / double(max(it, 1))));
            result = float2(v, v);
        } else {
            result = float2(sqrt(S.sumA), sqrt(S.sumB));
        }
    }
    field[row * p.fieldWidth + col] = result;
}

// MARK: Colour

struct ColorParams {
    float4 step;
    float4 start;
    float4 saturation;
    float4 offset;
    double renderScale;
    double xMin;
    double yMin;
    double dx;
    double dy;
    int blend;
    int rgbOrder;
    int sampling;
    int fieldWidth;
    int width;
    int rowStart;
    int rowCount;
};

// x87 fistp: round to nearest even; out-of-range gives the "integer indefinite" value.
inline int fround(double v) {
    if (!isfinite(v) || fabs(v) >= 2147483647.0) return -2147483647 - 1;
    return int(rint(v));
}

// 9-bit triangle fold: values 256...511 reflect back into 0...255.
inline int fold(int v) { return (v & 0x1ff) > 0xff ? (~v & 0xff) : v; }

// The original mixes its three per-channel slots in memory order R, B, G.
inline float3 slot(float4 v) { return float3(v.x, v.z, v.y); }

inline int3 trigBlend(int blend, double a, double b, float3 st, float3 sa, float3 sat, float3 off) {
    double ta = a * kTwoPi;
    double tb = b * kTwoPi;
    double v0;
    double v1;
    switch (blend) {
    case 1: v0 = sn(ta); v1 = cs(tb); break;
    case 2: v0 = cs(ta); v1 = -cs(tb); break;
    case 3: v0 = cs(ta); v1 = sn(tb); break;
    case 4:
    case 6: v0 = cs(ta); v1 = cs(tb); break;
    default: v0 = sn(ta); v1 = sn(tb); break;
    }
    double v2 = (v0 + v1) * 0.5;
    int s0 = fround(v0 * st.x + sa.x);
    int s1 = fround(v1 * st.y + sa.y);
    int s2 = fround(v2 * st.z + sa.z);
    int o0 = fround(double(s0) * sat.x + off.x) & 0x1ff;
    int o1 = fround(double(s1) * sat.y + off.y) & 0x1ff;
    int o2 = fround(double(s2) * sat.z + off.z) & 0x1ff;
    if (blend == 6 || blend == 7) {
        o2 = fround(0.33 * double(o0 + o1 + o2));
    }
    return int3(fold(o0), fold(o1), fold(o2));
}

inline int3 normalisedBlend(int blend, double a, double b, float3 st, float3 sa, float3 sat, float3 off) {
    double m = (a + b) * 0.5;
    double f0;
    double f1;
    double f2;
    switch (blend) {
    case 8:
        f0 = sn(kTwoPi * (a + m) * 0.5);
        f1 = -sn(kTwoPi * b);
        f2 = cs(kTwoPi * m);
        break;
    case 9:
        f0 = sn(kTwoPi * (-cs(a)));
        f1 = -sn(kTwoPi * sn(b));
        f2 = sn(kTwoPi * sn(m));
        break;
    case 10:
        f0 = sn(kTwoPi * a);
        f1 = -sn(kTwoPi * (b + m) * 0.5);
        f2 = sn(kTwoPi * m);
        break;
    case 11:
        f0 = sn(kTwoPi * a);
        f1 = -cs(kTwoPi * (m + b) * 0.5);
        f2 = -sn(kTwoPi * m);
        break;
    default:
        f0 = sn(kTwoPi * a);
        f1 = sn(kTwoPi * (m + b) * 0.5);
        f2 = sn(kTwoPi * m);
        break;
    }
    f0 = ((f0 * st.x + sa.x) * sat.x + off.x) / 255.0;
    f1 = ((f1 * st.y + sa.y) * sat.y + off.y) / 255.0;
    f2 = ((f2 * st.z + sa.z) * sat.z + off.z) / 255.0;

    double o0;
    double o1;
    double o2;
    switch (blend) {
    case 8: o0 = -sn(kTwoPi * f0); o1 = sn(kTwoPi * f1); o2 = -cs(kTwoPi * f2); break;
    case 9: o0 = sn(kTwoPi * f0); o1 = cs(kTwoPi * f1); o2 = sn(kTwoPi * f2); break;
    case 10: o0 = -sn(kTwoPi * f0); o1 = sn(kTwoPi * f1); o2 = sn(kTwoPi * f2); break;
    case 11: o0 = -cs(kTwoPi * f0); o1 = cs(kTwoPi * f1); o2 = sn(kTwoPi * f2); break;
    default: o0 = cs(kTwoPi * f0); o1 = cs(kTwoPi * f1); o2 = cs(kTwoPi * f2); break;
    }
    return int3(fround(o0 * 127.0) + 0x7f, fround(o1 * 127.0) + 0x7f, fround(o2 * 127.0) + 0x7f);
}

inline double nonZero(double v) { return fabs(v) < 1e-20 ? 1e-20 : v; }

inline int3 angleBlend(int blend, double a, double b, float2 pixel, float3 st, float3 sa, float3 sat, float3 off) {
    double d0 = 0.0;
    double d1 = 0.0;
    double d2 = 0.0;
    switch (blend) {
    case 13:
        d0 = sqrt(b * b + a * a);
        d1 = (a + d0) * 0.5;
        d2 = (b + d0) * 0.5;
        break;
    case 14:
    case 18:
        d0 = 0.707 * b + a;
        d1 = 0.707 * a + b;
        d2 = 0.707 * (d0 + d1);
        break;
    case 15:
        d0 = 0.707 * b + a;
        d1 = -0.707 * a + b;
        d2 = 0.707 * (d0 + d1);
        break;
    case 16:
        d0 = 0.707 * b;
        d1 = 0.707 * a;
        d2 = 0.707 * (d0 + d1);
        break;
    case 17:
        d0 = 0.707 * b * b;
        d1 = 0.707 * a * a;
        d2 = 0.707 * (d0 + d1);
        break;
    case 19:
        d0 = sqrt(b * b + a * a);
        d1 = a + d0;
        d2 = b + d0;
        break;
    case 20:
        d0 = b * b + a * a;
        d1 = a * a;
        d2 = b * b;
        break;
    case 21:
        d0 = a + b;
        d1 = a + d0;
        d2 = b + d0;
        break;
    case 22: {
        double px = nonZero(pixel.x);
        double py = nonZero(pixel.y);
        d2 = a + b + atan(fabs(px / py));
        d1 = b + a + atan(fabs(py / px));
        d0 = (d2 + d1) * 0.5;
        break;
    }
    case 23: {
        double ca = nonZero(a);
        double cb = nonZero(b);
        d0 = ca + cb;
        d2 = sn(fabs(pixel.x * pixel.x + ca)) + d0;
        d1 = sn(fabs(pixel.y * pixel.y + cb)) + d0;
        break;
    }
    case 24:
        d0 = fabs(b);
        d1 = a + d0;
        d2 = b + d0;
        d0 = (d1 + d2) * 0.5;
        break;
    case 25: {
        double px = nonZero(pixel.x);
        double py = nonZero(pixel.y);
        d0 = fabs(atan(fabs(px / py)) + atan(fabs(py / px)));
        d1 = a * d0;
        d2 = b * d0;
        break;
    }
    default:
        d0 = a + b;
        d1 = float(d0) * 0.5f * float(a);
        d2 = float(d0) * 0.5f * float(b);
        break;
    }

    // The original scales by 360 degrees and converts back, so the offset is in degrees.
    double deg0 = d0 * 360.0 * sat.x + off.x;
    double deg1 = d1 * 360.0 * sat.y + off.y;
    double deg2 = d2 * 360.0 * sat.z + off.z;
    const double toRadians = kPi / 180.0;
    double s0 = sn(deg0 * toRadians);
    double s1 = (sn(deg1 * toRadians) + s0) * 0.5;
    double s2 = 0.33 * (cs(deg2 * toRadians) + s0 + s1);
    return int3(fround(s0 * st.x + sa.x), fround(s1 * st.y + sa.y), fround(s2 * st.z + sa.z));
}

inline int3 colorAt(const ColorParams &p, double rawA, double rawB, float2 pixel) {
    double a = rawA * p.renderScale;
    double b = rawB * p.renderScale;
    if (a == 0.0 && b == 0.0) return int3(0);

    float3 st = slot(p.step);
    float3 sa = slot(p.start);
    float3 sat = slot(p.saturation);
    float3 off = slot(p.offset);
    int blend = clamp(p.blend, 1, 26);

    int3 o;
    if (blend <= 7) {
        o = trigBlend(blend, a, b, st, sa, sat, off);
    } else if (blend <= 12) {
        o = normalisedBlend(blend, a, b, st, sa, sat, off);
    } else {
        o = angleBlend(blend, a, b, pixel, st, sa, sat, off);
    }
    o &= 0xff;

    switch (p.rgbOrder) {
    case 2: return int3(o.x, o.z, o.y);
    case 3: return int3(o.y, o.z, o.x);
    case 4: return int3(o.y, o.x, o.z);
    case 5: return int3(o.z, o.x, o.y);
    case 6: return int3(o.z, o.y, o.x);
    default: return o;
    }
}

 void colorKernel(const ColorParams &p ,
                        const  float2 *field ,
                         uint *out ,
                        uint2 gid ) {
    if (int(gid.x) >= p.width || int(gid.y) >= p.rowCount) return;
    int col = int(gid.x);
    int row = p.rowStart + int(gid.y);
    int k = p.sampling;

    int3 sum = int3(0);
    for (int sy = 0; sy < k; sy++) {
        for (int sx = 0; sx < k; sx++) {
            int fr = row * k + sy;
            int fc = col * k + sx;
            float2 ab = field[fr * p.fieldWidth + fc];
            float2 pixel = float2(p.xMin + double(fc) * p.dx, p.yMin + double(fr) * p.dy);
            sum += colorAt(p, ab.x, ab.y, pixel);
        }
    }
    int3 avg = sum / (k * k);
    out[row * p.width + col] = uint(avg.x) | (uint(avg.y) << 8) | (uint(avg.z) << 16) | 0xff000000u;
}
